(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma call_slot (T : Type) (pc : Z) (args : T -> bvmap 5 word -> (word -> option byte) -> Z -> Z -> PM.pst -> Prop) (F : T -> list Z -> st -> st)
    (a : T) (q : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  PECS.eslot_spec RSEGS CAD EE L HI P T pc args (fun _ => PECS.mp_enc) F ->
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q -> getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 440) ->
  args a Ri Mi (sp - 64) fb si ->
  PECS.mp_enc p Y -> s_bad (F a p Y) = false -> PESK.sp_hb P (s_hi (F a p Y)) ->
  (forall fx2 R2 M2 md2 cr2 en2 k2 e2, regs_preserved Ri R2 -> mid fx2 R2 M2 md2 cr2 si smi en2 k2 e2 (F a p Y) ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri pc Mi mdi) K.
Proof.
  intros ES MID Q1 Qok X10 ARGS MPE NB' HB' CONT.
  destruct facts_ok as (RAok & Rra & Rsp & A16 & SLO & SHI & STOP & F1 & F2 & F3).
  destruct ENT as (_ & _ & _ & Rgp & Rtp & _). rewrite L5K.rl3 in Rgp. rewrite L5K.rl4 in Rtp.
  pose proof MID as (X2 & X8 & X9 & X18 & CS & C8 & C16 & C24 & C32 & C40 & C48 & STK & MB & MOKi & HHi & CPRE1 & STEP & EIMP & EK & DK & CK).
  pose proof MOKi as (Mh & Ml & Mm). pose proof STK as (_ & _ & _ & _ & SDEF).
  set (LB := PEC.owned si eni ki ++ LBX) in *.
  assert (BR : PMFR.brange L LB) by (apply (PMFR.brange_of_heap L HI HIok LB LB cri Mi _ HHi); apply incl_refl).
  assert (PINC : incl (PM.parser_own si) LB).
  { unfold LB, PEC.owned. intros x Hx. apply in_or_app. left. apply in_or_app. left. exact Hx. }
  assert (XINC : incl LBX (PM.parser_own si ++ LBX)) by (apply incl_appr; apply incl_refl).
  assert (STKc : L5C.stk (hl_sptop L) Mi (sp - 64) 20480).
  { apply (PMK.stk_call L Mi sp 26624 (sp - 64) 20480 STK); [lia|lia|lia|]. replace (sp - 64) with (sp + (-4) * 16) by lia. rewrite Z.mod_add by lia. exact A16. }
  (* [comment removed for export] *)
  assert (CREDe : PMSP.credit_le (PEC.pot_enc L P eni ki) cri).
  { pose proof (PMPK.credit_le_keep cr cri _ _ CRED CK) as CLE.
    destruct CPRE1 as (PA & _ & _ & _ & _ & _ & _ & TBOK & _).
    pose proof PA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & TBA & PVEC & _). destruct TBA as (_ & _ & TBF). destruct TBOK as (TG1 & TG2 & _).
    pose proof PVEC as (_ & _ & _ & Hk & _).
    assert (KPM0 : 0 <= hl_k_per_malloc L) by (pose proof (ly_kpm L LY); lia).
    assert (BOV0 : 0 <= hl_b_overhead L) by (pose proof (ly_bov L LY); lia).
    assert (CAPB : 0 <= PM.vs_cap (PM.p_tb si) <= 2 ^ 27).
    { destruct (PM.p_tb si) as [n1|c1 n1 q1]; cbn [PM.vs_cap] in *; [lia| destruct TBF as (_ & _ & _ & _ & Hc1 & _); lia]. }
    pose proof (PM.pow2_pos (PM.p_k si + 1) ltac:(lia)) as P2a. assert (P2b : 2 ^ (PM.p_k si + 1) <= 2 ^ 12) by (apply Z.pow_le_mono_r; lia).
    unfold PMSP.credit_le, PEC.pot_all, PEC.pot_enc, PEC.credit_add, PM.pot_parser, PM.credit_add, PM.pot_stack, PM.pot_text in CLE |- *.
    cbn [fst snd] in CLE |- *. split; nia. }
  unfold PECS.eslot_spec in ES.
  apply (ES SPM a fxi Ri Mi mdi K LBX cri (sp - 64) q fb cat p Y si str smi eni ki ei HHi MOKi K0).
  { unfold PMSP.entry. rewrite L5K.rl1, L5K.rl2, L5K.rl3, L5K.rl4. split; [exact Q1|]. split; [exact Qok|]. split; [exact X2|].
    split; [rewrite (CS 3%nat) by (cbn; tauto); exact Rgp|]. split; [rewrite (CS 4%nat) by (cbn; tauto); exact Rtp|]. exact STKc. }
  { unfold PMSP.frame_ok. cbn [pa_frame CAD PeCLayoutS.CADDR_S]. split; [lia|]. split; [lia| exact F3]. }
  { rewrite L5K.rl10. unfold PMSP.o_v. cbn [pa_off_v CAD PeCLayoutS.CADDR_S]. exact X10. }
  { exact ARGS. }
  { exact CPRE1. }
  { exact INCS. }
  { exact POK. }
  { exact MPE. }
  { exact NB'. }
  { exact HB'. }
  { exact CREDe. }
  intros fx2 R2 M2 md2 en2 k2 e2 cr2 RP2 CPRE2 EIMP2 HP2 CK2 MB2 HH2.
  change (PMSP.pm_scr 4) with 20480 in HP2.
  pose proof (PMK.ek_of_hpres L (PM.parser_own si ++ LBX) (sp - 64) 20480 (PEC.W_enc CAD EE fb) Mi M2 HP2) as EK2.
  assert (WCE : forall a1, PMK.inW (PEC.W_enc CAD EE fb) a1 ->
            (fb + 440 <= a1 < fb + 496) \/ (fb + 496 <= a1 < fb + 520) \/ (fb + 16 <= a1 < fb + 32) \/ (0xc9640 <= a1 < 0xc9640 + 2) \/ (0xeb088 <= a1 < 0xeb088 + 544)).
  { intros a1 (r0 & Hin & Hr). unfold PEC.W_enc, PMSP.err_W, PMSP.o_v, PMSP.o_ec, PESK.o_sink in Hin.
    cbn [pa_off_v pa_off_ec pe_off_sink pa_errcat_guard pa_atexit CAD EE PeCLayoutS.CADDR_S PeCLayoutS.EADDR_S app] in Hin.
    unfold L5.in_rng in Hr. destruct Hin as [<-|[<-|[<-|[<-|[<-|[]]]]]]; cbn [fst snd] in Hr; lia. }
  assert (SC4 : 0 <= 20480) by (clear; lia).
  assert (CKEEP : forall a1 v, sp - 48 <= a1 -> a1 + 8 <= sp -> L5.u64_at RSEGS Mi a1 v -> L5.u64_at RSEGS M2 a1 v).
  { intros a1 v Ha1 Ha2 Hc. apply (PMFR.u64_keep RSEGS L KL (PM.parser_own si ++ LBX) (sp - 64) 20480 _ Mi M2 EK2 STKc SC4); [lia|lia| | exact Hc].
    intros i Hi I. apply WCE in I. clear - Hi I F1 SLO STOP Ha1 Ha2. lia. }
  apply (CONT fx2 R2 M2 md2 cr2 en2 k2 e2 RP2). unfold mid.
  split; [rewrite (PMK.cs_of_preserved Ri R2 2%nat RP2) by PMK.inl; exact X2|].
  split; [rewrite (PMK.cs_of_preserved Ri R2 8%nat RP2) by PMK.inl; exact X8|].
  split; [rewrite (PMK.cs_of_preserved Ri R2 9%nat RP2) by PMK.inl; exact X9|].
