(* [comment removed for export] *)
Lemma call_span (len q : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_more Y = true -> s_done Y = false -> 0 <= s_pos Y <= blen p ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q ->
  getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 48 + 24) -> getr Ri (PMK.reg 11) = Z_to_bv 64 len -> getr Ri (PMK.reg 12) = Z_to_bv 64 (fb + 48 + 336) -> 0 <= len < 2 ^ 64 ->
  (forall fx2 R2 M2 md2 cr2 s2 sm2 ptr n, regs_preserved Ri R2 -> getr R2 (PMK.reg 10) = Z_to_bv 64 ptr -> getr R2 (PMK.reg 11) = Z_to_bv 64 n ->
      0 <= n <= len -> n < 2 ^ 26 ->
      ((ptr = 0 /\ n = 0) \/ (exists B m, In (B, m) (PM.parser_own s2) /\ B <= ptr /\ ptr + n <= B + m) \/ (fb + 48 + 336 + 1 <= ptr /\ ptr + n <= fb + 48 + 336 + 24)) ->
      L5.defined M2 ptr n -> L5.bytes_at RSEGS M2 ptr (UbjRef.slice p (s_pos Y) n) -> n = Z.min len (blen p - s_pos Y) ->
      mid fx2 R2 M2 md2 cr2 s2 sm2 eni ki ei (w_pos (s_pos Y + n) Y) ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 md2) K) ->
